// A2A 1.0.0, JSON-RPC 2.0 `message/send`. ONE crossing.
const a2aPayload = JSON.stringify({
  jsonrpc: "2.0",
  id: crypto.randomUUID(),
  method: "message/send",
  params: {
    message: {
      role: "user",
      messageId: crypto.randomUUID(),
      parts: [{ kind: "text", text: message }],
      metadata: { "revl.skill": "invoice-lookup" },
    },
  },
});
const a2aSend = (u: string) => fetch(u, {
  method: "POST",
  // Nothing is followed by the runtime; see the policy below.
  redirect: "manual",
  // A crossing that never returns is not a crossing.
  signal: AbortSignal.timeout(30 * 1000),
  headers: { "content-type": "application/json" },
  body: a2aPayload,
});

// -- redirect policy (revl.crossing_redirect) --------------------
// `redirect: "manual"` above: nothing is followed by the runtime. A
// 3xx is a REFUSAL — the endpoint is part of what was declared and
// admitted, and the Fetch standard re-issues a 301/302/303 POST as a
// GET with the body dropped, to whatever origin `Location` names.
const a2aFollowRedirects = false;
const a2aOriginOf = (u: string) => {
  const p = new URL(u);
  return `${p.protocol}//${p.host}`;
};
let a2aUrl: string = "https://billing.internal:8443/a2a";
let res = await a2aSend(a2aUrl);
for (let hop = 0; ; hop++) {
  const moved = res.type === "opaqueredirect"
    || (res.status >= 300 && res.status < 400);
  if (!moved) break;
  // An opaque redirect exposes no headers, so `location` reads null
  // and the refusal below is the only reachable answer for it.
  const loc = res.headers.get("location");
  if (!a2aFollowRedirects || loc === null) {
    throw new Error(
      `a2a: redirect refused — HTTP ${res.status}. Following a redirect is not declared on this crossing, and the endpoint is part of what was declared and admitted.`);
  }
  // Reported as an ORIGIN, never as the raw `Location`: that is
  // peer-supplied text and its userinfo would be a live credential.
  const next = new URL(loc, a2aUrl).toString();
  if (a2aOriginOf(next) !== a2aOriginOf(a2aUrl)) {
    throw new Error(
      `a2a: redirect refused — HTTP ${res.status} to ${a2aOriginOf(next)}. A declared follow is SAME-ORIGIN only; the declared endpoint is the reach bound.`);
  }
  if (res.status !== 307 && res.status !== 308) {
    throw new Error(
      `a2a: redirect refused — HTTP ${res.status} re-issues a POST as a GET and drops the body, so the declared emission would become a read. Only 307 and 308 preserve the method.`);
  }
  if (hop >= 4) {
    throw new Error(
      "a2a: redirect refused — too many same-origin hops; a declared follow does not chase a loop.");
  }
  a2aUrl = next;
  res = await a2aSend(a2aUrl);
}
if (!res.ok) {
  // A transport failure is a FAULT, never a quietly-empty result.
  throw new Error(`a2a: transport failure (HTTP ${res.status})`);
}
const rpc = await res.json();
if (rpc && rpc.error) {
  throw new Error(`a2a: JSON-RPC error ${rpc.error.code}`);
}
const result = rpc ? rpc.result : undefined;
if (!result) {
  throw new Error("a2a: response carried no result");
}
// A direct Message reply is already terminal; a Task is terminal only in
// the states A2A 1.0.0 says are.
const kind = result.kind;
const terminal = ["completed", "failed", "canceled", "rejected"];
if (kind === "task") {
  const state = result.status ? result.status.state : undefined;
  if (!terminal.includes(state)) {
    // Item 439's open question: a task still in flight is a LIFECYCLE
    // this slice does not express. Refuse; never poll, never resume.
    throw new Error(
      `a2a: task returned non-terminal state '${state}' — this binding crosses once and does not poll`);
  }
  if (state !== "completed") {
    throw new Error(`a2a: task ended '${state}'`);
  }
} else if (kind !== "message") {
  throw new Error(`a2a: unexpected result kind '${kind}'`);
}
// The reply is the peer's JSON and nothing about it is typed: `res.json()`
// is `any` on every ts lib, so an unannotated `(p) => ...` here is an
// implicit `any` parameter and `tsc --strict` refuses the module (issue
// #251, the second defect the a2a-to-ts fixture found). The shape below
// is a CLAIM being checked, not a type being trusted — every field stays
// optional and the `kind`/`typeof` guards below do the real work.
type A2aPart = { kind?: unknown; text?: unknown };
type A2aArtifact = { parts?: A2aPart[] };
const parts: A2aPart[] = kind === "task"
  ? ((result.artifacts as A2aArtifact[] | undefined) || [])
      .flatMap((a: A2aArtifact) => a.parts || [])
  : ((result.parts as A2aPart[] | undefined) || []);
const text = parts
  .filter((p: A2aPart) => p && p.kind === "text" && typeof p.text === "string")
  .map((p: A2aPart) => p.text as string)
  .join("");
if (text.length === 0 && parts.length > 0) {
  throw new Error("a2a: reply carried only non-text parts");
}
return text;

